operation.query:
SET @ReturnValue = 0;
INSERT INTO [GBVAttachmentDedicated] ([GBVID] ,[Filename] ,[FileAttached] ,[ContentType] ,[CreationUserID] ,[LastModificationTimestamp] ,[LastModificationUserID] ,[Deleted]) VALUES (@GBVID ,@Filename ,@FileAttached ,@ContentType ,@CreationUserID ,@LastModificationTimestamp ,@LastModificationUserID ,0);
SET @ReturnValue = SCOPE_IDENTITY();

IF(NOT EXISTS (SELECT GBVAttachmentID FROM GBVAttachmentDedicated WHERE DELETED = 0 AND GBVAttachmentID = @GBVAttachmentID)) SET @ReturnValue = 0;
ELSE
BEGIN
UPDATE [GBVAttachmentDedicated] SET [LastModificationTimestamp] = GETDATE() ,[LastModificationUserID] = @UserID ,[Deleted] = 1 WHERE GBVAttachmentID = @GBVAttachmentID
SET @ReturnValue = 1;
END
